/* Renders the demo from data.js (generated by `npm run build-site`) and switches language. */

const { docs } = window.DOCFLOW_DEMO;
const LANG_KEY = "docflow-lang";

const TEXT = {
  th: {
    title: "DocFlow TH: ตรวจเอกสารจัดซื้อก่อนจ่ายเงิน",
    readyNote: "ไม่มีเรื่องที่ต้องหยุดตรวจ",
    reviewNote: "ระบบส่งให้คนตรวจ ไม่ผ่านอัตโนมัติ",
    found: "สิ่งที่ระบบพบ",
    noFindings: "ไม่พบปัญหา",
    passed: (n) => `ตรวจผ่าน ${n} รายการ`,
    line: "ข้อความสรุปทาง LINE",
    read: "ข้อมูลที่ AI อ่านได้",
    open: "เปิดภาพขนาดเต็ม",
    alt: (label) => `ภาพเอกสารตัวอย่าง: ${label}`,
    item: "รายการ",
    qty: "จำนวน",
    price: "ราคา/หน่วย",
    total: "จำนวนเงิน",
    error: "ผิดพลาด",
    warning: "เตือน",
    info: "แจ้งให้ทราบ",
  },
  en: {
    title: "DocFlow TH: check purchasing documents before you pay",
    readyNote: "Nothing that has to stop for a review",
    reviewNote: "Sent to a person, not passed automatically",
    found: "What the checks found",
    noFindings: "No problems found",
    passed: (n) => `${n} checks passed`,
    line: "LINE summary message",
    read: "What the AI read",
    open: "Open full-size image",
    alt: (label) => `Sample document image: ${label}`,
    item: "Item",
    qty: "Qty",
    price: "Unit price",
    total: "Amount",
    error: "Error",
    warning: "Warning",
    info: "Note",
  },
};

function loadLang() {
  try {
    return localStorage.getItem(LANG_KEY) === "en" ? "en" : "th";
  } catch {
    return "th";
  }
}

function saveLang(value) {
  try {
    localStorage.setItem(LANG_KEY, value);
  } catch {
    // Private windows may block storage; the choice just won't be remembered.
  }
}

let lang = loadLang();
let selected = 0;

function el(tag, attrs = {}, children = []) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (key === "text") node.textContent = value;
    else node.setAttribute(key, value);
  }
  for (const child of children) node.append(child);
  return node;
}

const staticText = [...document.querySelectorAll("[data-en]")].map((node) => ({
  node,
  th: node.textContent.trim().replace(/\s+/g, " "),
  en: node.dataset.en,
}));

function renderTabs() {
  const tabs = document.getElementById("tabs");
  tabs.replaceChildren(
    ...docs.map((doc, index) => {
      const isSelected = index === selected;
      const tab = el(
        "button",
        {
          type: "button",
          class: "tab",
          role: "tab",
          id: `tab-${index}`,
          "aria-selected": String(isSelected),
          "aria-controls": "panel",
          tabindex: isSelected ? "0" : "-1",
        },
        [el("span", { class: `dot ${doc.status}`, "aria-hidden": "true" }), doc.label[lang]],
      );
      tab.addEventListener("click", () => select(index));
      return tab;
    }),
  );
}

function card(title, children) {
  return el("section", { class: "card" }, [el("h3", { text: title }), ...children]);
}

function renderPanel() {
  const doc = docs[selected];
  const t = TEXT[lang];
  const panel = document.getElementById("panel");
  panel.setAttribute("aria-labelledby", `tab-${selected}`);

  const figure = el("figure", { class: "doc-frame" }, [
    el("a", { href: doc.image, target: "_blank", rel: "noopener" }, [
      el("img", {
        src: doc.image,
        alt: t.alt(doc.label[lang]),
        width: "1240",
        height: "1754",
      }),
    ]),
    el("figcaption", {}, [
      el("a", { href: doc.image, target: "_blank", rel: "noopener", text: t.open }),
    ]),
  ]);

  const status = el("section", { class: "card" }, [
    el("div", { class: "status-row" }, [
      el("span", { class: `status ${doc.status}`, text: doc.statusLabel[lang] }),
      el("span", {
        class: "status-note",
        text: doc.status === "ready" ? t.readyNote : t.reviewNote,
      }),
    ]),
  ]);

  const findings = doc.findings.length
    ? el(
        "ul",
        { class: "findings" },
        doc.findings.map((finding) =>
          el("li", { class: "finding" }, [
            el("span", { class: `sev ${finding.severity}`, text: t[finding.severity] }),
            el("span", { text: finding[lang] }),
          ]),
        ),
      )
    : el("p", { class: "none", text: t.noFindings });
  const passed = el("details", {}, [
    el("summary", { text: t.passed(doc.passed.length) }),
    el(
      "ul",
      { class: "passed" },
      doc.passed.map((item) => el("li", { text: item[lang] })),
    ),
  ]);

  const facts = el(
    "dl",
    { class: "facts" },
    doc.facts.flatMap((fact) => [
      el("dt", { text: fact.label[lang] }),
      el("dd", { text: fact.value[lang] }),
    ]),
  );
  const lines = el("div", { class: "table-wrap" }, [
    el("table", { class: "lines" }, [
      el("thead", {}, [
        el("tr", {}, [
          el("th", { text: t.item, scope: "col" }),
          el("th", { class: "r", text: t.qty, scope: "col" }),
          el("th", { class: "r", text: t.price, scope: "col" }),
          el("th", { class: "r", text: t.total, scope: "col" }),
        ]),
      ]),
      el(
        "tbody",
        {},
        doc.lines.map((line) =>
          el("tr", {}, [
            el("td", { text: line.description }),
            el("td", { class: "r", text: line.quantity }),
            el("td", { class: "r", text: line.unitPrice }),
            el("td", { class: "r", text: line.lineTotal }),
          ]),
        ),
      ),
    ]),
  ]);

  panel.replaceChildren(
    figure,
    el("div", {}, [
      status,
      card(t.found, [findings, passed]),
      card(t.line, [el("p", { class: "bubble", text: doc.summary[lang] })]),
      card(t.read, [facts, lines]),
    ]),
  );
}

function renderLanguage() {
  document.documentElement.lang = lang;
  document.title = TEXT[lang].title;
  for (const { node, th, en } of staticText) node.textContent = lang === "en" ? en : th;
  for (const button of document.querySelectorAll("[data-lang]")) {
    button.setAttribute("aria-pressed", String(button.dataset.lang === lang));
  }
  renderTabs();
  renderPanel();
}

function select(index, focus = false) {
  selected = (index + docs.length) % docs.length;
  renderTabs();
  renderPanel();
  if (focus) document.getElementById(`tab-${selected}`).focus();
}

document.getElementById("tabs").addEventListener("keydown", (event) => {
  if (event.key === "ArrowRight") select(selected + 1, true);
  else if (event.key === "ArrowLeft") select(selected - 1, true);
  else if (event.key === "Home") select(0, true);
  else if (event.key === "End") select(docs.length - 1, true);
  else return;
  event.preventDefault();
});

for (const button of document.querySelectorAll("[data-lang]")) {
  button.addEventListener("click", () => {
    lang = button.dataset.lang;
    saveLang(lang);
    renderLanguage();
  });
}

renderLanguage();
